<script setup lang="ts">
import type { SatisfactionData, SatisfactionDefinition, SatisfactionQuestion, SatisfactionSection, SatisfactionResponse, SatisfactionAnswers } from '#shared/portal-satisfaction'
import { portalDate } from '~/types/portal'
const props=defineProps<{projectId:string;admin?:boolean}>()
const emit=defineEmits<{changed:[]}>()
const data=ref<SatisfactionData|null>(null),draft=ref<SatisfactionDefinition|null>(null),answers=ref<SatisfactionAnswers>({}),responses=ref<SatisfactionResponse[]>([]),selected=ref<SatisfactionResponse|null>(null)
const loading=ref(false),busy=ref(false),error=ref(''),success=ref(''),mode=ref<'preview'|'edit'|'responses'>('preview'),dirty=ref(false)
let generation=0
const clone=<T,>(value:T):T=>JSON.parse(JSON.stringify(value))
const load=async()=>{
 const current=++generation,projectId=props.projectId;loading.value=true;error.value=''
 try{const result=await $fetch<SatisfactionData>('/api/portal/satisfaction',{query:{projectId}});if(current!==generation)return;data.value=result;draft.value=clone(result.definition);answers.value={};dirty.value=false}
 catch(e:any){if(current===generation)error.value=e?.data?.statusMessage||'Impossible de charger le questionnaire.'}finally{if(current===generation)loading.value=false}
}
watch(()=>props.projectId,()=>{data.value=null;draft.value=null;responses.value=[];selected.value=null;mode.value=props.admin?'edit':'preview';answers.value={};dirty.value=false;success.value='';void load()},{immediate:true})
onBeforeUnmount(()=>{++generation})
const loadResponses=async()=>{
 mode.value='responses';selected.value=null;error.value='';const current=generation,projectId=props.projectId
 try{const result=await $fetch<{responses:SatisfactionResponse[]}>('/api/portal/satisfaction/responses',{query:{projectId}});if(current===generation)responses.value=result.responses}catch(e:any){if(current===generation)error.value=e?.data?.statusMessage||'Impossible de charger les réponses.'}
}
const save=async()=>{
 if(!draft.value||!data.value)return
 const current=generation,projectId=props.projectId;busy.value=true;error.value='';success.value=''
 try{const result=await $fetch<{definition:SatisfactionDefinition;revision:number}>('/api/portal/satisfaction',{method:'PUT',body:{projectId,revision:data.value.revision,definition:draft.value}});if(current!==generation)return;data.value={...data.value,...result};draft.value=clone(result.definition);dirty.value=false;success.value='Questionnaire enregistré et visible par le client.'}
 catch(e:any){if(current===generation)error.value=e?.data?.statusMessage||'Impossible d’enregistrer le questionnaire.'}finally{busy.value=false}
}
const submit=async()=>{
 if(!data.value)return
 const current=generation,projectId=props.projectId;busy.value=true;error.value='';success.value=''
 try{const result=await $fetch<{response:SatisfactionResponse}>('/api/portal/satisfaction',{method:'POST',body:{projectId,revision:data.value.revision,answers:answers.value}});if(current!==generation)return;data.value.response=result.response;data.value.permissions.canSubmit=false;success.value='Merci ! Votre retour a bien été envoyé à MC Studio.';emit('changed')}
 catch(e:any){if(current===generation)error.value=e?.data?.statusMessage||'Impossible d’envoyer votre retour.'}finally{busy.value=false}
}
const uid=()=>`item-${crypto.randomUUID()}`
const addSection=()=>{draft.value?.sections.push({id:uid(),title:'Nouvelle section',description:'',questions:[]});dirty.value=true}
const addQuestion=(section:SatisfactionSection)=>{section.questions.push({id:uid(),label:'Nouvelle question',description:'',type:'text',required:false,options:[]});dirty.value=true}
const move=<T,>(list:T[],index:number,offset:number)=>{const destination=index+offset;if(destination<0||destination>=list.length)return;const item=list.splice(index,1)[0]!;list.splice(destination,0,item);dirty.value=true}
const changeType=(q:SatisfactionQuestion)=>{q.options=q.type==='choice'?['Oui','Non']:[];dirty.value=true}
const optionsText=(q:SatisfactionQuestion,event:Event)=>{q.options=(event.target as HTMLTextAreaElement).value.split('\n');dirty.value=true}
const saved=computed(()=>selected.value||(!props.admin?data.value?.response:null))
const definition=computed(()=>saved.value?.definition||(props.admin?draft.value:data.value?.definition))
const displayedAnswers=computed(()=>saved.value?.answers||answers.value)
const readonly=computed(()=>Boolean(props.admin||saved.value||!data.value?.permissions.canSubmit))
const questionCount=computed(()=>definition.value?.sections.reduce((total,s)=>total+s.questions.length,0)||0)
const answered=computed(()=>Object.values(displayedAnswers.value).filter(value=>value!==''&&value!==undefined).length)
const removeSection=(index:number)=>{draft.value?.sections.splice(index,1);dirty.value=true}
const removeQuestion=(section:SatisfactionSection,index:number)=>{section.questions.splice(index,1);dirty.value=true}
</script>

<template>
 <section class="satisfaction" :class="{embedded:admin}" aria-label="Questionnaire de satisfaction">
  <header class="sat-heading"><div><span class="sat-eyebrow"><UIcon name="i-tabler-heart-handshake"/>RETOUR D’EXPÉRIENCE</span><h2>Satisfaction</h2><p>{{admin?'Un questionnaire à votre image, pour chaque projet.':'Un projet se termine. La conversation continue.'}}</p></div><span v-if="data" class="sat-badge">{{data.project.name}}</span></header>
  <nav v-if="admin" class="sat-tabs" aria-label="Gestion du questionnaire"><button :class="{active:mode==='edit'}" @click="mode='edit';selected=null">Modifier le questionnaire<span v-if="dirty"> ·</span></button><button :class="{active:mode==='preview'}" @click="mode='preview';selected=null">Aperçu client</button><button :class="{active:mode==='responses'}" @click="loadResponses">Réponses reçues</button></nav>
  <p v-if="error" class="sat-alert error" role="alert">{{error}} <button v-if="!data" type="button" @click="load">Réessayer</button></p><p v-if="success" class="sat-alert success" role="status">{{success}}</p>
  <p v-if="loading" class="sat-muted" role="status">Chargement du questionnaire…</p>
  <template v-else-if="data">
   <form v-if="admin&&mode==='edit'&&draft" class="sat-editor" @submit.prevent="save" @input="dirty=true">
    <div class="sat-editor-intro"><div><h3>Votre questionnaire</h3><p>Les modifications s’appliquent à ce projet. Les réponses déjà envoyées conservent leur questionnaire d’origine.</p></div><span class="sat-badge">{{dirty?'Modifications non enregistrées':'Enregistré'}}</span></div>
    <fieldset :disabled="busy"><div class="sat-fields"><label>Titre<input v-model="draft.title" required maxlength="160"></label><label>Description<textarea v-model="draft.description" rows="3" maxlength="3000"/></label><div class="sat-columns"><label>Lien d’avis Google<input v-model="draft.googleReviewUrl" type="url" maxlength="2000" placeholder="https://…"><small>Laissez vide pour masquer le lien.</small></label><label>Lien de recommandation<input v-model="draft.referralUrl" type="url" maxlength="2000" placeholder="https://…"><small>Laissez vide pour masquer le lien.</small></label></div></div>
    <article v-for="(section,index) in draft.sections" :key="section.id" class="sat-edit-section"><header><span class="sat-eyebrow">SECTION {{index+1}}</span><div class="sat-controls"><button type="button" :disabled="index===0" :aria-label="'Monter la section '+section.title" @click="move(draft.sections,index,-1)">↑</button><button type="button" :disabled="index===draft.sections.length-1" :aria-label="'Descendre la section '+section.title" @click="move(draft.sections,index,1)">↓</button><button type="button" :disabled="draft.sections.length===1" :aria-label="'Supprimer la section '+section.title" @click="removeSection(index)">Supprimer</button></div></header><div class="sat-fields"><label>Titre de la section<input v-model="section.title" required maxlength="160"></label><label>Description de la section<textarea v-model="section.description" rows="2" maxlength="2000"/></label></div>
     <article v-for="(q,qi) in section.questions" :key="q.id" class="sat-edit-question"><header><strong>Question {{qi+1}}</strong><div class="sat-controls"><button type="button" :disabled="qi===0" :aria-label="'Monter la question '+q.label" @click="move(section.questions,qi,-1)">↑</button><button type="button" :disabled="qi===section.questions.length-1" :aria-label="'Descendre la question '+q.label" @click="move(section.questions,qi,1)">↓</button><button type="button" :aria-label="'Supprimer la question '+q.label" @click="removeQuestion(section,qi)">Supprimer</button></div></header><div class="sat-fields"><label>Question<input v-model="q.label" required maxlength="500"></label><label>Aide ou précision<textarea v-model="q.description" maxlength="1000" rows="2"/></label><div class="sat-columns"><label>Type de réponse<select v-model="q.type" @change="changeType(q)"><option value="text">Texte libre</option><option value="rating">Note de 1 à 10</option><option value="choice">Choix unique</option></select></label><label class="sat-check"><input v-model="q.required" type="checkbox">Réponse obligatoire</label></div><label v-if="q.type==='choice'">Choix proposés (un par ligne)<textarea :value="q.options.join('\n')" rows="4" @input="optionsText(q,$event)"/><small>2 à 20 choix distincts, 200 caractères par choix.</small></label></div></article>
     <button type="button" class="sat-secondary" :disabled="questionCount>=100||section.questions.length>=50" @click="addQuestion(section)"><UIcon name="i-tabler-plus"/>Ajouter une question</button>
    </article><button type="button" class="sat-secondary" :disabled="draft.sections.length>=20" @click="addSection"><UIcon name="i-tabler-plus"/>Ajouter une section</button></fieldset>
    <footer class="sat-editor-footer"><small>{{dirty?'Enregistrez pour publier vos modifications.':'Le questionnaire est visible dans l’espace client.'}}</small><button class="sat-primary" :disabled="busy||!dirty">{{busy?'Enregistrement…':'Enregistrer le questionnaire'}}</button></footer>
   </form>
   <template v-else>
    <template v-if="admin&&mode==='responses'&&!selected"><div class="sat-response-heading"><h3>Réponses reçues</h3><span>{{responses.length}} retour{{responses.length>1?'s':''}}</span></div><div v-if="!responses.length" class="sat-empty"><UIcon name="i-tabler-message-heart"/><h3>Les retours commencent ici</h3><p>Les réponses de votre équipe client apparaîtront ici après leur envoi.</p></div><button v-for="response in responses" :key="response.id" class="sat-response-row" @click="selected=response"><span><strong>{{response.respondent.name}}</strong><small>{{response.respondent.email}} · {{portalDate(response.submittedAt)}}</small></span><span>Lire le retour <UIcon name="i-tabler-arrow-up-right"/></span></button></template>
    <template v-else-if="definition"><button v-if="selected" type="button" class="sat-secondary sat-back" @click="selected=null">← Toutes les réponses</button>
     <article class="sat-document"><header class="sat-document-heading"><span class="sat-document-icon"><UIcon name="i-tabler-message-heart"/></span><span class="sat-eyebrow">MC STUDIO · VOTRE EXPÉRIENCE</span><h1>{{definition.title}}</h1><p>{{definition.description}}</p><span v-if="saved" class="sat-saved"><UIcon name="i-tabler-circle-check"/>Réponse envoyée le {{portalDate(saved.submittedAt)}}</span><span v-else class="sat-duration">{{questionCount}} questions · quelques minutes pour progresser ensemble</span></header>
     <div class="sat-project-info"><div><span>PROJET</span><strong>{{saved?.respondent.projectName||data.project.name}}</strong></div><div><span>CLIENT</span><strong>{{saved?.respondent.organizationName||data.project.organizationName}}</strong></div><div><span>{{admin&&!saved?'APERÇU':'VOTRE NOM'}}</span><strong>{{saved?.respondent.name||(admin?'Renseigné depuis le compte client':data.respondent.name)}}</strong></div></div>
     <p v-if="admin&&!saved" class="sat-note">Aperçu du questionnaire{{dirty?' avec vos modifications non enregistrées':''}}. L’envoi est réservé aux clients.</p><p v-else-if="!saved&&!data.permissions.canSubmit" class="sat-note">Votre rôle de lecteur vous permet de consulter le questionnaire.</p>
     <form @submit.prevent="submit"><fieldset :disabled="busy||readonly"><section v-for="(section,index) in definition.sections" :key="section.id" class="sat-section"><header><span class="sat-section-number">{{String(index+1).padStart(2,'0')}}</span><div><h3>{{section.title}}</h3><p v-if="section.description">{{section.description}}</p></div></header><div v-for="q in section.questions" :key="q.id" class="sat-question"><label :id="'label-'+q.id" :for="q.type==='text'?'answer-'+q.id:undefined">{{q.label}}<span v-if="q.required" class="sat-required"> *</span></label><p v-if="q.description" class="sat-help">{{q.description}}</p><p v-if="saved" class="sat-answer">{{displayedAnswers[q.id]===undefined?'Sans réponse':q.type==='rating'?displayedAnswers[q.id]+' / 10':displayedAnswers[q.id]}}</p><textarea v-else-if="q.type==='text'" :id="'answer-'+q.id" v-model="answers[q.id]" :required="q.required" maxlength="10000" rows="3" placeholder="Votre réponse…"/><div v-else-if="q.type==='rating'" class="sat-rating" role="group" :aria-labelledby="'label-'+q.id"><label v-for="n in 10" :key="n" :class="{chosen:answers[q.id]===n}"><input v-model="answers[q.id]" type="radio" :name="q.id" :value="n" :required="q.required"><span>{{n}}</span></label><div class="sat-rating-scale"><span>Pas du tout satisfait</span><span>Très satisfait</span></div></div><div v-else class="sat-choices" role="group" :aria-labelledby="'label-'+q.id"><label v-for="option in q.options" :key="option" :class="{chosen:answers[q.id]===option}"><input v-model="answers[q.id]" type="radio" :name="q.id" :value="option" :required="q.required"><span>{{option}}</span></label></div></div></section></fieldset>
      <div class="sat-links"><a v-if="definition.googleReviewUrl" :href="definition.googleReviewUrl" target="_blank" rel="noopener noreferrer"><UIcon name="i-tabler-brand-google"/><span><strong>Partager votre expérience</strong><small>Laisser un avis sur Google</small></span><UIcon name="i-tabler-arrow-up-right"/></a><a v-if="definition.referralUrl" :href="definition.referralUrl" target="_blank" rel="noopener noreferrer"><UIcon name="i-tabler-heart-handshake"/><span><strong>Recommander MC Studio</strong><small>Découvrir le programme d’apport d’affaires</small></span><UIcon name="i-tabler-arrow-up-right"/></a></div>
      <footer v-if="!saved&&!admin&&data.permissions.canSubmit" class="sat-submit"><div><strong>{{answered}} / {{questionCount}} réponses</strong><small>* Questions obligatoires · Vos réponses sont envoyées en une seule fois.</small></div><button class="sat-primary" :disabled="busy">{{busy?'Envoi en cours…':'Envoyer mon retour'}}<UIcon name="i-tabler-arrow-right"/></button></footer><p v-if="saved" class="sat-thanks">Merci d’avoir pris le temps de partager votre expérience.</p>
     </form></article>
    </template>
   </template>
  </template>
 </section>
</template>

<style scoped>
.satisfaction{padding:32px;color:var(--portal-text);font:14px/1.6 Inter,Arial,sans-serif;min-width:0}.satisfaction.embedded{padding:0}.satisfaction *{box-sizing:border-box}.satisfaction h1,.satisfaction h2,.satisfaction h3,.satisfaction p{margin:0}.satisfaction h1,.satisfaction h2,.satisfaction h3{color:var(--portal-text);font-family:inherit;font-weight:600;letter-spacing:-.035em}.satisfaction button,.satisfaction input,.satisfaction textarea,.satisfaction select{font:inherit}.satisfaction button{cursor:pointer}.satisfaction button:disabled{opacity:.45;cursor:default}.satisfaction :focus-visible{outline:2px solid var(--portal-accent);outline-offset:3px}.sat-heading{display:flex;justify-content:space-between;gap:20px;align-items:center;margin-bottom:28px}.sat-heading h2{font-size:28px;margin:6px 0}.sat-heading p,.sat-muted{color:var(--portal-muted);font-size:13px}.sat-eyebrow{display:flex;align-items:center;gap:8px;color:var(--portal-muted);font-size:10px;letter-spacing:.12em;font-weight:500}.sat-eyebrow .iconify{font-size:17px;color:var(--portal-accent-text)}.sat-badge{padding:6px 10px;border:1px solid var(--portal-line);border-radius:6px;color:var(--portal-muted);font-size:11px;max-width:260px;overflow-wrap:anywhere}.sat-tabs{display:flex;gap:6px;border-bottom:1px solid var(--portal-line);margin-bottom:28px;overflow:auto}.sat-tabs button{padding:12px;border:0;border-bottom:2px solid transparent;background:none;color:var(--portal-muted);font-size:12px;white-space:nowrap}.sat-tabs button.active{border-color:var(--portal-accent);color:var(--portal-text)}.sat-alert{padding:14px 16px!important;margin:0 0 24px!important;border:1px solid var(--portal-danger);background:var(--portal-danger-soft);color:var(--portal-danger);border-radius:8px}.sat-alert.success{color:var(--portal-success);border-color:var(--portal-success);background:var(--portal-success-soft)}.sat-alert button{border:0;background:transparent;text-decoration:underline;color:inherit}.sat-document{width:100%;min-width:0;margin:0;padding:28px 0 0;border-top:1px solid var(--portal-line)}.sat-document-heading{padding-bottom:32px}.sat-document-icon{display:grid;place-items:center;width:58px;height:58px;border:1px solid var(--portal-line);border-radius:14px;background:var(--portal-raised);color:var(--portal-accent-text);font-size:30px;margin-bottom:26px}.sat-document-heading h1{font-size:38px;line-height:1.2;margin:14px 0 18px;overflow-wrap:anywhere}.sat-document-heading>p{font-size:14px;color:var(--portal-muted);white-space:pre-wrap;line-height:1.9}.sat-duration,.sat-saved{display:flex;gap:7px;align-items:center;font-size:11px;color:var(--portal-muted);margin-top:20px}.sat-saved{color:var(--portal-success)}.sat-project-info{display:grid;grid-template-columns:1fr 1fr;gap:20px;padding:22px 24px;background:var(--portal-raised);border:1px solid var(--portal-line);border-radius:8px}.sat-project-info>div:last-child{grid-column:1/-1}.sat-project-info span{display:block;font-size:9px;color:var(--portal-muted);letter-spacing:.1em;margin-bottom:6px}.sat-project-info strong{font-size:13px;font-weight:500;overflow-wrap:anywhere}.sat-note{margin-top:24px!important;font-size:12px;color:var(--portal-muted);padding:12px 16px;border-left:2px solid var(--portal-accent);background:var(--portal-raised)}.satisfaction fieldset{border:0;padding:0;margin:0;min-width:0}.sat-section{padding:34px 0;border-bottom:1px solid var(--portal-line)}.sat-section>header{display:flex;gap:14px;align-items:flex-start}.sat-section-number{font-size:11px;line-height:28px;color:var(--portal-muted);font-variant-numeric:tabular-nums}.sat-section h3{font-size:21px;line-height:28px;overflow-wrap:anywhere}.sat-section header p{font-size:12px;line-height:1.8;color:var(--portal-muted);margin-top:8px;white-space:pre-wrap}.sat-question{margin-top:26px}.sat-question>label{display:block;font-size:13px;font-weight:500;margin-bottom:12px;overflow-wrap:anywhere}.sat-required{color:var(--portal-accent-text)}.sat-help{font-size:12px;c